/**
 * Raster overlay + legend.
 *
 * The point of these tests is that the legend shows the PICTURE's
 * colours. `tests/fixtures/raster_legend.json` is generated by the
 * renderer itself (backend/src/raster_scan/render.py), so if the ramp
 * or the hatch ever changes and the legend stops matching, these fail.
 */
import test, { before, after } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { createElement } from 'react'
import { renderToStaticMarkup } from 'react-dom/server'
import { createServer } from 'vite'
import react from '@vitejs/plugin-react'

let server
let RasterLegend
let RasterOverlay

before(async () => {
  server = await createServer({
    configFile: false,
    plugins: [react()],
    cacheDir: 'node_modules/.vite-raster-tests',
    optimizeDeps: { noDiscovery: true, include: [] },
    server: { middlewareMode: true, watch: null, hmr: false, ws: false },
    resolve: { alias: {
      'react-leaflet': fileURLToPath(new URL('./fixtures/leaflet.js', import.meta.url)),
    } },
  })
  ;({ default: RasterLegend } = await server.ssrLoadModule('/src/components/RasterLegend.jsx'))
  ;({ default: RasterOverlay } = await server.ssrLoadModule('/src/components/RasterOverlay.jsx'))
})

after(async () => server?.close())

const fixture = JSON.parse(
  readFileSync(new URL('./fixtures/raster_legend.json', import.meta.url), 'utf8'),
)

const legend = {
  value: {
    ramp_hex: fixture.ramp_hex,
    domain: fixture.domain,
    swatches: fixture.swatches,
    meaning: 'index reading at this cell -- a display ramp, not a risk score',
  },
  no_data: {
    base_rgba: fixture.no_data_base_rgba,
    stripe_rgba: fixture.no_data_stripe_rgba,
    meaning: 'inside the study area, no usable reading',
  },
  transparent: { rgba: [0, 0, 0, 0], meaning: 'outside the study area' },
}

test('every legend swatch is a colour the renderer actually painted with', () => {
  const html = renderToStaticMarkup(createElement(RasterLegend, { legend }))
  for (const swatch of fixture.swatches) {
    assert.ok(
      html.includes(swatch.hex),
      `legend is missing ${swatch.hex}, which the renderer produced at NDCI ${swatch.value}`,
    )
  }
})

test('the legend hardcodes no ramp colour of its own', () => {
  // If the component ever inlines the ramp, a legend rendered from
  // DIFFERENT served swatches would still show the old colours.
  const recoloured = {
    ...legend,
    value: {
      ...legend.value,
      swatches: fixture.swatches.map((s) => ({ ...s, hex: '#123456' })),
    },
  }
  const html = renderToStaticMarkup(createElement(RasterLegend, { legend: recoloured }))
  assert.ok(html.includes('#123456'), 'legend did not render the swatches it was given')
  for (const swatch of fixture.swatches) {
    assert.ok(
      !html.includes(swatch.hex),
      `legend still shows ${swatch.hex} after being given different colours -- it has its own copy`,
    )
  }
})

test('the legend says index value, not risk level', () => {
  const html = renderToStaticMarkup(createElement(RasterLegend, { legend }))
  assert.match(html, /ค่าดัชนี/)
  assert.match(html, /ไม่ใช่ระดับความเสี่ยง/)
  assert.doesNotMatch(html, /ความเสี่ยงสูง|เสี่ยงมาก|risk level/i)
})

test('unmeasured water gets its own swatch and is called out as not-a-low-reading', () => {
  const html = renderToStaticMarkup(createElement(RasterLegend, { legend }))
  const [r, g, b] = fixture.no_data_base_rgba
  assert.ok(
    html.includes(`rgba(${r}, ${g}, ${b}`),
    'the no-data hatch colour from the renderer is not shown in the legend',
  )
  assert.match(html, /ไม่ได้วัดค่า/)
  assert.match(html, /ไม่ใช่ค่าดัชนีต่ำ/)
})

test('the hatch swatch is achromatic and no ramp swatch is', () => {
  // The separation the overlay relies on, asserted on the legend too:
  // grey means "not measured" and the ramp never produces a grey.
  const [r, g, b] = fixture.no_data_base_rgba
  assert.equal(r, g)
  assert.equal(g, b)
  for (const swatch of fixture.swatches) {
    const [sr, sg, sb] = [1, 3, 5].map((i) => parseInt(swatch.hex.slice(i, i + 2), 16))
    assert.ok(
      !(sr === sg && sg === sb),
      `ramp swatch ${swatch.hex} is grey, which is the no-data colour`,
    )
  }
})

test('a legend with no data renders nothing rather than an empty scale', () => {
  assert.equal(renderToStaticMarkup(createElement(RasterLegend, { legend: null })), '')
})


test('the overlay is placed on the study polygon\'s own bounds', () => {
  // Bounds come from the renderer, which derives them from the polygon.
  // An ImageOverlay stretched to slightly wrong bounds misplaces every
  // pixel and nothing visibly fails, so this is asserted numerically
  // against the polygon bbox the backend computed.
  const data = { bounds: fixture.polygon_bbox, overlay_url: '/raster-scan/overlay.png' }
  const html = renderToStaticMarkup(createElement(RasterOverlay, { data }))
  const rendered = JSON.parse(html.match(/data-overlay-bounds="([^"]+)"/)[1].replace(/&quot;/g, '"'))
  assert.deepEqual(rendered, fixture.polygon_bbox)
})

test('the overlay carries the pixelated class that stops resampling blends', () => {
  const data = { bounds: fixture.polygon_bbox, overlay_url: '/raster-scan/overlay.png' }
  const html = renderToStaticMarkup(createElement(RasterOverlay, { data }))
  assert.match(html, /raster-overlay-image/)
  assert.match(html, /data-overlay-url="\/raster-scan\/overlay\.png"/)
})

test('no overlay is drawn when there is nothing rendered yet', () => {
  // An empty layer over the study area would assert "we looked and saw
  // nothing", which is not the same as "we have not looked".
  assert.equal(renderToStaticMarkup(createElement(RasterOverlay, { data: null })), '')
  assert.equal(
    renderToStaticMarkup(createElement(RasterOverlay, { data: { bounds: null, overlay_url: null } })),
    '',
  )
})
